include { FREYJA_VARIANTS   } from 'nf-core/freyja/variants'
include { FREYJA_UPDATE     } from 'nf-core/freyja/update'
include { FREYJA_DEMIX      } from 'nf-core/freyja/demix'
include { FREYJA_BOOT       } from 'nf-core/freyja/boot'

workflow BAM_VARIANT_DEMIX_BOOT_FREYJA {

    take:
    ch_bam               // channel: [ val(meta), path(bam) ]
    ch_fasta_fai         // channel: [ val(meta), path(fasta), path(fai) ]
    val_skip_boot        // value skip_boot
    val_repeats          // value repeats
    val_db_name          // string db_name
    ch_barcodes          // channel:  [ path(barcodes)]
    ch_lineages_meta     // channel:  [ path(lineages_meta)]
    ch_lineages_topology // channel:  [ path(lineages_topology)]

    main:
    //
    // Variant calling
    //
    FREYJA_VARIANTS (
        ch_bam,
        ch_fasta_fai
    )
    ch_freyja_variants = FREYJA_VARIANTS.out.variants

    //
    // Update the database if none are given.
    //
    if (!ch_barcodes ) {
        // Throw warning if meta or topology are provided but no barcodes
        if (ch_lineages_meta || ch_lineages_topology) {
            log.warn("Lineage metadata or topology provided without barcodes. The database will be updated but the provided metadata/topology will be ignored.")
        }
        FREYJA_UPDATE (
            val_db_name
        )
        ch_barcodes          = FREYJA_UPDATE.out.barcodes
        ch_lineages_meta     = FREYJA_UPDATE.out.lineages_meta
        ch_lineages_topology = FREYJA_UPDATE.out.lineages_topology
    }

    //
    // demix and define minimum variant abundances
    //
    FREYJA_DEMIX (
        ch_freyja_variants,
        ch_barcodes,
        ch_lineages_meta,
        ch_lineages_topology
    )

    //
    // Perform bootstrapping to get more accurate estimates of abundances
    //
    ch_lineages   = channel.empty()
    ch_summarized = channel.empty()
    if (!val_skip_boot){
        FREYJA_BOOT (
            ch_freyja_variants,
            val_repeats,
            ch_barcodes,
            ch_lineages_meta,
            ch_lineages_topology
        )
        ch_lineages   = FREYJA_BOOT.out.lineages
        ch_summarized = FREYJA_BOOT.out.summarized
    }

    emit:
    variants          = FREYJA_VARIANTS.out.variants  // channel: [ val(meta), path(variants_tsv), path(depths_tsv) ]
    demix             = FREYJA_DEMIX.out.demix        // channel: [ val(meta), path(demix_tsv) ]
    lineages          = ch_lineages                   // channel: [ val(meta), path(lineages_csv) ]
    summarized        = ch_summarized                 // channel: [ val(meta), path(summarized_csv) ]
    barcodes          = ch_barcodes                   // channel: [ path(barcodes) ]
    lineages_meta     = ch_lineages_meta              // channel: [ path(lineages_meta) ]
    lineages_topology = ch_lineages_topology          // channel: [ path(lineages_topology) ]
    }

nextflow_workflow {

    name "Test Workflow BAM_VARIANT_DEMIX_BOOT_FREYJA"
    script "../main.nf"
    workflow "BAM_VARIANT_DEMIX_BOOT_FREYJA"
    config "./nextflow.config"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "bam_variant_demix_boot_freyja"
    tag "subworkflows/bam_variant_demix_boot_freyja"
    tag "freyja"
    tag "freyja/variants"
    tag "freyja/update"
    tag "freyja/demix"
    tag "freyja/boot"

    test("sarscov2 - bam - val - nodb"){

        when {
            params {
                module_args = '--depthcutoff 1'
            }

            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[2] = false
                input[3] = 3
                input[4] = 'freyja_db'
                input[5] = []
                input[6] = []
                input[7] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                // All depend on a database that gets updated regularly
                { assert path(workflow.out.demix.get(0).get(1)).getText().contains("summarized") },
                { assert path(workflow.out.summarized.get(0).get(1)).getText().contains("0.025,") },
                { assert path(workflow.out.lineages.get(0).get(1)).getText().contains("0.025,") },
                { assert snapshot(
                    workflow.out.variants,
                    file(workflow.out.lineages_meta.get(0)).name,
                    file(workflow.out.lineages_topology.get(0)).name,
                    file(workflow.out.barcodes.get(0)).name,
                ).match() },
            )
        }
    }

    test("sarscov2 - bam - val - db"){

        setup {
            run("FREYJA_UPDATE") {
                script "../../../../modules/nf-core/freyja/update/main.nf"
                process {
                    """
                    input[0] = "test_db"
                    """
                }
            }
        }

        when {
            params {
                module_args = '--depthcutoff 1'
            }

            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[2] = false
                input[3] = 3
                input[4] = 'test_db'
                input[5] = FREYJA_UPDATE.out.barcodes
                input[6] = FREYJA_UPDATE.out.lineages_meta
                input[7] = FREYJA_UPDATE.out.lineages_topology
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                // All depend on a database that gets updated regularly
                { assert path(workflow.out.demix.get(0).get(1)).getText().contains("summarized") },
                { assert path(workflow.out.summarized.get(0).get(1)).getText().contains("0.025,") },
                { assert path(workflow.out.lineages.get(0).get(1)).getText().contains("0.025,") },
                { assert snapshot(
                    workflow.out.variants,
                    file(workflow.out.lineages_meta.get(0)).name,
                    file(workflow.out.lineages_topology.get(0)).name,
                    file(workflow.out.barcodes.get(0)).name,
                ).match() },
            )
        }
    }

    test("sarscov2 - bam - skip - val - nodb"){

        when {
            params {
                module_args = '--depthcutoff 1'
            }

            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[2] = true     // skip bootstrapping
                input[3] = 0
                input[4] = 'test_db'
                input[5] = []
                input[6] = []
                input[7] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                // All depend on a database that gets updated regularly
                { assert path(workflow.out.demix.get(0).get(1)).getText().contains("summarized") },
                { assert snapshot(
                    workflow.out.variants,
                    file(workflow.out.lineages_meta.get(0)).name,
                    file(workflow.out.lineages_topology.get(0)).name,
                    file(workflow.out.barcodes.get(0)).name,
                ).match() },
            )
        }
    }

    test("sarscov2 - bam - val - nodb - stub"){

        options "-stub"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[2] = false
                input[3] = 3
                input[4] = 'freyja_db'
                input[5] = []
                input[6] = []
                input[7] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(sanitizeOutput(workflow.out)).match() },
            )
        }
    }

}

